<script lang="ts">
 import {onDestroy} from 'svelte';import AttachmentCard from './AttachmentCard.svelte';import {prepareAttachment,storeAttachment,attachments,ATTACHMENTS,type Attachment} from '../core/attachments';import {downloadedModels,DEFAULT_MODEL} from '../audio/models';import {transcribeOwned} from '../audio/service';import type {Core} from '../core/core';
 let {core,value,mediaEnabled,audioEnabled,transcriptionEnabled,onchange,onpersist}:{core:Core;value:Attachment[];mediaEnabled:boolean;audioEnabled:boolean;transcriptionEnabled:boolean;onchange:(value:Attachment[])=>void;onpersist:()=>Promise<string>}=$props();
 let input:HTMLInputElement,photo:HTMLInputElement,video:HTMLInputElement;let error=$state(''),busy=$state(false),recording=$state(false),elapsed=$state(0);let recorder:MediaRecorder|undefined,stream:MediaStream|undefined,timer:ReturnType<typeof setInterval>,alive=true,owner='',started=0,bytes=0;
 let picker:HTMLDivElement,anchor:HTMLButtonElement|undefined,left=$state(0),top=$state(0);
 export function open(button:HTMLButtonElement){anchor=button;if(picker.matches(':popover-open')){picker.hidePopover();return;}const box=button.getBoundingClientRect();left=Math.max(12,Math.min(box.left,innerWidth-284));top=Math.max(12,Math.min(box.bottom+8,innerHeight-270));picker.showPopover();picker.querySelector<HTMLButtonElement>('[role=menuitem]')?.focus();}
 function choose(action:()=>void){picker.hidePopover();action();}
 function pickerKeys(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();picker.hidePopover();anchor?.focus();return;}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const items=[...picker.querySelectorAll<HTMLButtonElement>('[role=menuitem]')],index=items.indexOf(document.activeElement as HTMLButtonElement);items[event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowUp'?-1:1)+items.length)%items.length]?.focus();}
 function change(next:Attachment[]){if(alive)onchange(next);}
 async function add(file:Blob,name:string){busy=true;error='';try{const payload=await prepareAttachment(file,name);await storeAttachment(core.storage,payload);change([...value.filter(a=>a.id!==payload.meta.id),payload.meta]);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 export async function files(files:FileList|File[]){for(const file of Array.from(files))if((mediaEnabled&&/^(image|video)\//.test(file.type))||(audioEnabled&&file.type.startsWith('audio/')))await add(file,file.name);}
 function stop(){if(recorder&&recorder.state!=='inactive'){busy=true;recorder.stop();}stream?.getTracks().forEach(t=>t.stop());clearInterval(timer);recording=false;}
 async function record(){if(busy)return;if(recording){stop();return;}error='';busy=true;try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined')throw Error('Браузер не поддерживает запись. Можно загрузить аудиофайл.');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,channelCount:1},video:false});owner=await onpersist();const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(type=>MediaRecorder.isTypeSupported(type));recorder=new MediaRecorder(stream,{audioBitsPerSecond:64000,...(mime?{mimeType:mime}:{})});const parts:Blob[]=[];const currentRecorder=recorder;bytes=0;started=Date.now();elapsed=0;
 recorder.ondataavailable=e=>{if(e.data.size){parts.push(e.data);bytes+=e.data.size;if(bytes>24*1024*1024)stop();}};
 recorder.onerror=()=>{error='Запись прервана. Сохраняем полученный звук.';stop();};
 recorder.onstop=async()=>{const blob=new Blob(parts,{type:currentRecorder.mimeType});let staged=false;try{if(!blob.size)throw Error('Микрофон не записал звук.');const payload=await prepareAttachment(blob,'Запись '+new Date().toLocaleString('ru-RU').replace(/[/:]/g,'-')+(blob.type.includes('ogg')?'.ogg':blob.type.includes('mp4')?'.m4a':'.webm'));await storeAttachment(core.storage,payload);const recovery=await core.storage.getSetting<any[]>('recording-recovery')||[];await core.storage.transaction([{kind:'setting',key:'recording-recovery',value:[...recovery,{note:owner,properties:{[ATTACHMENTS]:[payload.meta]}}]}]);staged=true;const current=core.data.atoms.find(a=>a.id===owner);const next=current?[...attachments(current),payload.meta]:[payload.meta];if(current){const saved=await core.update(owner,{properties:{...current.properties,[ATTACHMENTS]:next}});window.dispatchEvent(new CustomEvent('phosphoreya:media-saved',{detail:{note:owner,beforeRevision:current.revision,revision:saved.revision}}));}else await core.create({title:'Сохранённая аудиозапись',properties:{[ATTACHMENTS]:next}});await core.storage.transaction([{kind:'setting',key:'recording-recovery',value:(await core.storage.getSetting<any[]>('recording-recovery')||[]).filter(item=>!attachments(item).some(a=>a.id===payload.meta.id))}]);change([...value.filter(a=>a.id!==payload.meta.id),payload.meta]);if(transcriptionEnabled&&current&&await core.storage.getSetting('plugin:builtin.audio:autoTranscribe')!==false){const model=await core.storage.getSetting<string>('plugin:builtin.transcription:model')||DEFAULT_MODEL;if((await downloadedModels()).includes(model))void transcribeOwned(core,owner,payload.meta).catch(()=>{});}}catch(e){error=(e as Error).message;core.emit('media:error',{message:error,...(!staged?{recording:blob}:{})});}finally{busy=false;}};
 recorder.start(1000);recording=true;busy=false;timer=setInterval(()=>{elapsed=Math.floor((Date.now()-started)/1000);if(elapsed>=1800)stop();},500);
 }catch(e){stream?.getTracks().forEach(t=>t.stop());busy=false;error=(e as Error).message;}}
 async function transcribe(meta:Attachment){error='';try{const note=await onpersist();await transcribeOwned(core,note,meta);}catch(e){error=(e as Error).message;}}
 $effect(()=>{if(!audioEnabled&&recording)stop();});$effect(()=>{if(!recording&&!busy)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue='';};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);});onDestroy(()=>{alive=false;stop();});
</script>
<div class="note-media">
 <div bind:this={picker} popover="auto" data-escape-local="true" class="attachment-picker" style:left={`${left}px`} style:top={`${top}px`} role="menu" tabindex="-1" aria-label="Прикрепить к заметке" onkeydowncapture={pickerKeys} ontoggle={event=>{anchor?.setAttribute('aria-expanded',String(event.newState==='open'));if(event.newState==='closed'&&document.activeElement===document.body)anchor?.focus();}}>
  <div class="picker-heading"><span>Прикрепить</span><button type="button" aria-label="Закрыть вложения" onclick={()=>{picker.hidePopover();anchor?.focus();}}><svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
  {#if mediaEnabled}<button type="button" role="menuitem" disabled={busy} onclick={()=>choose(()=>photo.click())}><svg viewBox="0 0 24 24"><path d="M8 6 9.5 4h5L16 6h4a1 1 0 0 1 1 1v12H3V7a1 1 0 0 1 1-1Z"/><circle cx="12" cy="12" r="3.5"/></svg><span>Снять фото</span></button><button type="button" role="menuitem" disabled={busy} onclick={()=>choose(()=>video.click())}><svg viewBox="0 0 24 24"><rect x="3" y="6" width="12" height="12" rx="3"/><path d="m15 10 6-3v10l-6-3"/></svg><span>Снять видео</span></button>{/if}
  {#if mediaEnabled||audioEnabled}<button type="button" role="menuitem" disabled={busy} onclick={()=>choose(()=>input.click())}><svg viewBox="0 0 24 24"><path d="m8 12 6-6a3 3 0 0 1 4 4l-8 8a4.5 4.5 0 0 1-6.4-6.4l8.5-8.5"/></svg><span>Выбрать файл<small>Фото, видео или аудио · до 25 МБ</small></span></button>{/if}
  {#if audioEnabled}<button type="button" role="menuitem" disabled={busy} onclick={()=>choose(()=>void record())}><svg viewBox="0 0 24 24"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3m-4 0h8"/></svg><span>{recording?'Остановить запись':'Записать звук'}</span></button>{/if}
 </div>
 {#if recording}<button type="button" class="recording-status" onclick={stop}><span class="recording-dot"></span><span>{Math.floor(elapsed/60)}:{String(elapsed%60).padStart(2,'0')}</span><svg viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="2"/></svg><span>Остановить</span></button>{/if}
 <input bind:this={input} type="file" aria-label="Добавить медиа" hidden multiple accept={[mediaEnabled?'image/*,video/*':'',audioEnabled?'audio/*':''].filter(Boolean).join(',')} onchange={e=>{if(e.currentTarget.files)void files(e.currentTarget.files);e.currentTarget.value='';}}/>
 <input bind:this={photo} type="file" aria-label="Снять фото" hidden accept="image/*" capture="environment" onchange={e=>{if(e.currentTarget.files)void files(e.currentTarget.files);e.currentTarget.value='';}}/>
 <input bind:this={video} type="file" aria-label="Снять видео" hidden accept="video/*" capture="environment" onchange={e=>{if(e.currentTarget.files)void files(e.currentTarget.files);e.currentTarget.value='';}}/>
 {#if busy}<p role="status">Сохраняем вложение…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}
 {#each value as item (item.id)}<AttachmentCard value={item} storage={core.storage} transcription={transcriptionEnabled} onremove={()=>change(value.filter(a=>a.id!==item.id))} ontext={text=>change(value.map(a=>a.id===item.id?{...a,transcript:text}:a))} ontranscribe={()=>transcribe(item)}/>{/each}
</div>
<style>
 .note-media{flex:none;min-width:0}.attachment-picker{position:fixed;margin:0;width:min(272px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;padding:7px;border:1px solid var(--theme-border);border-radius:22px;background:var(--theme-surface);color:var(--theme-text);box-shadow:0 12px 40px #0003;transform-origin:top left}.attachment-picker:popover-open{animation:picker-in 180ms cubic-bezier(.16,1,.3,1)}.picker-heading{display:flex;align-items:center;justify-content:space-between;padding:0 4px 2px 11px;font-size:12px;color:var(--theme-muted)}.picker-heading button{display:grid;place-items:center;min-height:36px;width:36px;padding:8px;border:0;background:transparent}.attachment-picker [role=menuitem]{display:flex;align-items:center;gap:13px;width:100%;min-height:48px;padding:10px 12px;border:0;border-radius:15px;background:transparent;color:var(--theme-text);text-align:left;font-size:14px}.attachment-picker svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}.attachment-picker small{display:block;font-size:10px;color:var(--theme-muted);margin-top:3px}.attachment-picker button:focus-visible{outline:2px solid var(--theme-accent);outline-offset:-2px}.recording-status{display:flex;align-items:center;gap:9px;min-height:44px;padding:8px 12px;border:1px solid var(--theme-border);background:var(--theme-surfaceAlt);border-radius:22px;font-size:12px;font-variant-numeric:tabular-nums;color:var(--theme-text)}.recording-dot{width:7px;height:7px;border-radius:50%;background:var(--theme-danger)}.recording-status svg{width:14px;height:14px;fill:currentColor}p{font-size:12px;color:var(--theme-muted)}@media(hover:hover) and (pointer:fine){.attachment-picker [role=menuitem]:hover{background:var(--theme-surfaceAlt)}}@keyframes picker-in{from{opacity:0;transform:translateY(-5px) scale(.97)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.attachment-picker:popover-open{animation:none}}
</style>
